import{_ as e}from"./plugin-vue_export-helper-c27b6911.js";import{o,c as d,e as i}from"./app-db7b9325.js";const a={},r=i('<h1 id="jadx-gui-逆向分析工具指南" tabindex="-1"><a class="header-anchor" href="#jadx-gui-逆向分析工具指南" aria-hidden="true">#</a> JADX-GUI 逆向分析工具指南</h1><p>JADX 是一款将 Android APK、DEX、JAR 等文件反编译为 Java 源码的可视化工具。</p><h2 id="_1-核心功能" tabindex="-1"><a class="header-anchor" href="#_1-核心功能" aria-hidden="true">#</a> 1. 核心功能</h2><ul><li><strong>反编译</strong>: 将 DEX 转换为可读的 Java 代码。</li><li><strong>资源解析</strong>: 解析 <code>AndroidManifest.xml</code>、<code>res</code> 目录及 <code>resources.arsc</code>。</li><li><strong>查找引用</strong>: 快速定位变量、方法、类在何处被使用。</li><li><strong>重命名/重构</strong>: 对混淆后的类名、方法名进行重命名，方便理解逻辑（仅内存中，不修改 APK）。</li><li><strong>去混淆 (Deobfuscation)</strong>: 自动尝试恢复被混淆的包结构和名称。</li></ul><h2 id="_2-常用快捷键-windows-mac" tabindex="-1"><a class="header-anchor" href="#_2-常用快捷键-windows-mac" aria-hidden="true">#</a> 2. 常用快捷键 (Windows/Mac)</h2><ul><li><code>Ctrl + N</code> / <code>Cmd + O</code>: 全局搜索（类、方法、字段）。</li><li><code>Ctrl + Shift + N</code> / <code>Cmd + Shift + O</code>: 搜索文件。</li><li><code>Ctrl + F</code>: 在当前编辑框内查找。</li><li><code>X</code>: 查看选中项的<strong>引用 (Usage)</strong>。</li><li><code>R</code>: <strong>重命名</strong>选中的类、方法或字段。</li><li><code>G</code>: 跳转到声明处。</li><li><code>Ctrl + Enter</code>: 在新标签页中打开。</li></ul><h2 id="_3-推荐设置" tabindex="-1"><a class="header-anchor" href="#_3-推荐设置" aria-hidden="true">#</a> 3. 推荐设置</h2><ul><li><strong>File -&gt; Save as Gradle project</strong>: 将反编译结果导出为标准的 Android Studio 项目，方便进行全文搜索和动态调试。</li><li><strong>Options -&gt; Preferences</strong>: <ul><li><code>Deobfuscation</code>: 开启后，jadx 会自动给混淆后的 <code>a, b, c</code> 类起一个唯一的、基于包名的名字，极大提高阅读体验。</li><li><code>Inline anonymous classes</code>: 开启可减少代码嵌套。</li><li><code>Show inconsistent code</code>: 显示由于优化导致的反编译不完全的代码。</li></ul></li></ul><h2 id="_4-插件支持" tabindex="-1"><a class="header-anchor" href="#_4-插件支持" aria-hidden="true">#</a> 4. 插件支持</h2><p>JADX 支持插件扩展，常见的有：</p><ul><li><strong>Frida snippet</strong>: 直接生成针对当前选中方法的 Frida Hook 脚本片段。</li><li><strong>Scripting</strong>: 使用 Groovy 编写脚本批量处理任务。</li></ul><h2 id="_5-命令行版本-jadx" tabindex="-1"><a class="header-anchor" href="#_5-命令行版本-jadx" aria-hidden="true">#</a> 5. 命令行版本 (jadx)</h2><p>如果你需要批量处理或在服务器上运行：</p><ul><li><code>jadx -d out-dir app.apk</code>: 将 APK 反编译到指定目录。</li><li><code>jadx --export-gradle app.apk</code>: 导出为 Gradle 项目。</li><li><code>jadx -j 8 app.apk</code>: 使用 8 个线程并行处理。</li></ul>',14),l=[r];function c(t,n){return o(),d("div",null,l)}const u=e(a,[["render",c],["__file","jadx-gui.html.vue"]]);export{u as default};
